        String year = request == null || request.year() == null ? "" : request.year().trim();
        if (!YEAR.matcher(year).matches()) {
            throw new InvalidPeriodException("Not a valid year: " + year);
        }
        body.set(new GenerateQuartersInput(Integer.parseInt(year)));
    }
}
